/**
 * Quality Gate pre-import — detect "workflow merdosi" generated by Liara.
 *
 * Filosofia: l'AI può produrre output SINTATTICAMENTE valido (Zod-passes)
 * ma SEMANTICAMENTE rotto (reference circolari, mock URL, dead-end branch,
 * placeholder fake che non funzioneranno mai a runtime). Questo gate
 * impedisce che un workflow non-eseguibile venga importato come "completo"
 * — preserva la promessa "premi Importa → funziona".
 *
 * 5 categorie di rules:
 *   1. CIRCULAR — nodo X.config referencia `{{$node.Y.json…}}` MA X precede
 *      Y nel DAG (Y non è ancora eseguito quando X parte).
 *   2. MOCK_PLACEHOLDER — config field contiene example.com, localhost,
 *      noreply@example.com, smtp.example.com, etc → non funzionerà mai.
 *   3. SWITCH_NO_DEFAULT — logic_switch senza defaultCase → documento "altro"
 *      diventa orphan a runtime.
 *   4. DEAD_END — branch interno termina senza output (non-leaf, non-sink).
 *      Es. logic_if → slack ma niente else → metà documenti spariscono.
 *   5. ORPHAN_TRIGGER — trigger senza edges in uscita → mai eseguibile.
 *
 * Severity:
 *   - critical → throw AiScaffoldError, workflow REJECTED + salvato come
 *     "esempio negativo" per training futuro
 *   - medium → notes warning all'utente, importabile ma con avviso
 *   - info → solo log server-side (no UI noise)
 *
 * Pure function: nessun side effect, testabile a moduli. Estratta da
 * singleshot.service.ts per modularità (NO MONOLITI rule).
 */

import { logger } from '@/lib/logger.js';
import {
  isArrayProducer,
  isScalarConsumer,
  isAggregator,
  isLoopBodyPassthrough,
} from '@/services/ai-scaffold/node-shape.js';
import { detectCodeLanguage, LANG_FOR_CODE_NODE } from '@/services/ai-scaffold/code-lang.js';
import { checkEspressioneNuda } from '@/services/ai-scaffold/rule-espressione-nuda.js';
import { checkNienteDaElaborare } from '@/services/ai-scaffold/rule-niente-da-elaborare.js';
import { checkListaCheNonArriva } from '@/services/ai-scaffold/rule-lista-che-non-arriva.js';
import { checkRegoleCondizione } from '@/services/ai-scaffold/rule-regole-condizione.js';
import { runSemanticRules } from '@/services/ai-scaffold/semantic-rules.js';

export type QualitySeverity = 'critical' | 'medium' | 'info';
export type QualityCode =
  | 'CIRCULAR_REFERENCE'
  | 'MOCK_PLACEHOLDER'
  | 'SWITCH_NO_DEFAULT'
  | 'DEAD_END_BRANCH'
  | 'ORPHAN_TRIGGER'
  | 'DUPLICATE_NODES'
  | 'SUSPICIOUS_RESOURCE_ID'
  | 'SWITCH_INVALID_CASE_KEY'
  | 'AGGREGATION_INSIDE_LOOP'
  | 'ARRAY_TO_SCALAR_WITHOUT_LOOP'
  | 'FAN_IN_WITHOUT_MERGE'
  | 'DB_TABLE_NOT_IN_SCHEMA'
  | 'DB_COLUMN_NOT_IN_SCHEMA'
  | 'CODE_NODE_LANG_MISMATCH'
  | 'OBSOLETE_MODEL'
  // ── Semantica (semantic-rules.ts + semantic-rules-config.ts) ───────────
  | 'ERROR_BRANCH_INVERTED'
  | 'ERROR_HANDLER_NO_SINK'
  | 'LOOKUP_WITHOUT_BRANCH'
  | 'TRIGGER_WITHOUT_ACTION'
  | 'AUDIT_NOT_TERMINAL'
  | 'SENSITIVE_HARDCODED'
  // ── Espressioni (rule-espressione-nuda.ts) ─────────────────────────────
  | 'ESPRESSIONE_NON_RISOLVIBILE'
  // ── Flusso senza materia (rule-niente-da-elaborare.ts) ─────────────────
  | 'NIENTE_DA_ELABORARE'
  // ── Condizioni che non si valutano (rule-regole-condizione.ts) ─────────
  | 'REGOLE_CONDIZIONE_MALFORMATE'
  // ── Un filtro su ciò che lista non è (rule-lista-che-non-arriva.ts) ────
  | 'LISTA_CHE_NON_ARRIVA';

export interface QualityIssue {
  severity: QualitySeverity;
  code: QualityCode;
  nodeId?: string;
  field?: string;
  message: string;
}

export interface QualityGateInput {
  nodes: {
    id: string;
    defId: string;
    config: Record<string, unknown>;
  }[];
  edges: {
    from: string;
    to: string;
  }[];
  /**
   * Tenant database catalog (passed by singleshot.service). Used by
   * `DB_TABLE_NOT_IN_SCHEMA` rule to ensure `db_query`/`db_insert` reference
   * a real table. Optional — when omitted the rule is skipped.
   *
   * `columns` (table name → column names) abilita la rule
   * `DB_COLUMN_NOT_IN_SCHEMA`: verifica che `rowJson`/`whereJson`/`patchJson`
   * di db_insert/update/delete referenzino SOLO colonne esistenti. Quando
   * assente, la sola rule colonna è skippata (table check resta attivo).
   */
  databases?: readonly {
    id: string;
    tables: readonly string[];
    columns?: Readonly<Record<string, readonly string[]>>;
  }[];
}

export interface QualityGateResult {
  ok: boolean;
  issues: QualityIssue[];
  /** True se almeno un issue ha severity 'critical' → reject + save negative. */
  shouldReject: boolean;
}

